<header class="panel-page-heading"><div><span>Administracao</span><h1>Eventos Asaas</h1><p>Recepcao, processamento e conciliacao dos webhooks.</p></div></header>
<section class="panel-card"><form class="billing-filter-form" method="get" action="<?= url('/admin/asaas-eventos') ?>"><label>Status <input name="status" maxlength="20" value="<?= e($filtros['status']) ?>"></label><label>Tipo <input name="tipo" maxlength="120" value="<?= e($filtros['tipo']) ?>"></label><label>Payment ID <input name="payment" maxlength="120" value="<?= e($filtros['payment']) ?>"></label><label>Data <input type="date" name="data" value="<?= e($filtros['data']) ?>"></label><button class="btn btn-primary" type="submit">Filtrar</button></form></section>
<section class="panel-card"><div class="responsive-table"><table class="panel-table"><thead><tr><th>Recebido</th><th>Evento</th><th>Tipo</th><th>Payment ID</th><th>Status</th><th>Tentativas</th><th></th></tr></thead><tbody><?php foreach($eventos as$evento):?><tr><td><?= e(date('d/m/Y H:i',strtotime($evento['recebido_em']))) ?></td><td><?= e($evento['asaas_event_id']) ?></td><td><?= e($evento['tipo_evento']) ?></td><td><?= e((string)$evento['asaas_payment_id']) ?></td><td><span class="status-pill"><?= e($evento['status_processamento']) ?></span></td><td><?= (int)$evento['quantidade_tentativas'] ?></td><td><a class="btn btn-outline" href="<?= url('/admin/asaas-eventos/'.(int)$evento['id']) ?>">Detalhes</a></td></tr><?php endforeach;?></tbody></table></div><?php if(!$eventos):?><p>Nenhum evento encontrado.</p><?php endif;?></section>
